var e=[{id:`pl-quick-01`,category:`quick`,length:`short`,difficulty:`easy`,text:`Spóźnię się 10 minut, zacznijcie beze mnie.`},{id:`pl-quick-02`,category:`quick`,length:`short`,difficulty:`easy`,text:`Możesz mi wysłać adres?`},{id:`pl-quick-03`,category:`quick`,length:`short`,difficulty:`easy`,text:`Dzięki, do usłyszenia!`},{id:`pl-quick-04`,category:`quick`,length:`short`,difficulty:`easy`,text:`Już jadę, będę za pięć minut.`},{id:`pl-quick-05`,category:`quick`,length:`short`,difficulty:`easy`,text:`Pasuje mi, do zobaczenia.`},{id:`pl-quick-06`,category:`quick`,length:`short`,difficulty:`easy`,text:`Właśnie wróciłam do domu, zadzwonię za chwilę.`},{id:`pl-quick-07`,category:`quick`,length:`short`,difficulty:`easy`,text:`Dostałeś moją ostatnią wiadomość?`},{id:`pl-quick-08`,category:`quick`,length:`short`,difficulty:`medium`,text:`Nic się nie stało, nie spiesz się. Zajmę nam stolik.`},{id:`pl-quick-09`,category:`quick`,length:`short`,difficulty:`easy`,text:`Zaraz będę, zajmij mi miejsce.`},{id:`pl-quick-10`,category:`quick`,length:`short`,difficulty:`easy`,text:`O której ci pasuje?`},{id:`pl-quick-11`,category:`quick`,length:`short`,difficulty:`easy`,text:`Przepraszam, nie ten czat!`},{id:`pl-quick-12`,category:`quick`,length:`short`,difficulty:`easy`,text:`Sprawdzę i dam ci znać.`},{id:`pl-quick-13`,category:`quick`,length:`short`,difficulty:`easy`,text:`Powodzenia dzisiaj, dasz radę!`},{id:`pl-quick-14`,category:`quick`,length:`short`,difficulty:`easy`,text:`Zadzwoń, jak będziesz wolny.`},{id:`pl-quick-15`,category:`quick`,length:`short`,difficulty:`easy`,text:`Jestem pod blokiem, schodź.`},{id:`pl-quick-16`,category:`quick`,length:`short`,difficulty:`easy`,text:`Możemy to przełożyć na jutro?`},{id:`pl-quick-17`,category:`quick`,length:`short`,difficulty:`easy`,text:`Jasne, nie ma sprawy.`},{id:`pl-quick-18`,category:`quick`,length:`short`,difficulty:`easy`,text:`Stoję w korku, niedługo będę.`},{id:`pl-quick-19`,category:`quick`,length:`short`,difficulty:`easy`,text:`Jadłaś już? Zamawiam pizzę.`},{id:`pl-quick-20`,category:`quick`,length:`short`,difficulty:`easy`,text:`Dzięki za pomoc, mam u ciebie dług.`},{id:`pl-quick-21`,category:`quick`,length:`short`,difficulty:`easy`,text:`Tym razem nie zapomnij kluczy.`},{id:`pl-quick-22`,category:`quick`,length:`short`,difficulty:`easy`,text:`Dopiero to zobaczyłem, daj mi dwie minuty.`},{id:`pl-quick-23`,category:`quick`,length:`short`,difficulty:`medium`,text:`Wchodzę na spotkanie, odezwę się później.`},{id:`pl-quick-24`,category:`quick`,length:`short`,difficulty:`medium`,text:`Tak! Wchodzę w to. Co mam przynieść?`}];export{e as default};